1	/**
2	 * Screen 04 milestone M4 (round 8, qa/match/04/NOTES.md) — sub-switches of `?match04=1`, each `&m04…=1`, default off:
3	 *  m04ring  — the gold washer opening and the gold-ring tunnel as REAL modeled geometry (lathe profiles sized from the
4	 *             approved picture's mouth ring r 3.58 → 4.11 and the painted stacked ring bands), shaded as polished gold
5	 *             (warm glow down the tunnel, pink / violet / cyan water reflections on the lower walls, glints, a row of
6	 *             amber bulbs on the opening and on every ring lip). In the approved view these surfaces show the approved
7	 *             pixels (camera projection, unchanged); they fade to their own crisp 3D gold as the camera leaves that view.
8	 *  m04foam  — puffy 3D foam banks along both water edges (the painted white-lilac foam clusters), hidden in the approved
9	 *             view (the painting carries them there), shown once the camera has left it.
10	 *  m04bub   — iridescent soap bubbles floating in the tunnel air (camera-facing bubble discs), same visibility rule.
11	 *  m04arrow — the five glowing blue chevron arrows drawn crisp on the water (distance-field shape at the painted
12	 *             spacing) instead of the magnified painted arrow tile.
13	 *  m04wave  — the painted swirl water without the obvious repeat (two offset samples of the swirl tile blended by a
14	 *             slow world-anchored noise) and flowing down the slide.
15	 *  m04foam3 — (round 9, with m04foam + m04river) LOW soft foam hugging the river banks (heaps a third as tall, smaller
16	 *             puffs, wider gaps where the pink water shows), lavender / pink shaded like the painted foam.
17	 *  m04pink  — (round 9, with m04river) the broad pink / magenta swirl bands on both sides of the narrow cyan arrow lane.
18	 *  m04arr5  — (round 9, with m04river) the five glowing chevrons as painted: fat flat white-cyan bars nested one after
19	 *             the other ahead of Benny (about five in view at a time, the farther ones fading into the glow).
20	 *  m04mouth — (round 9, needs m04ring) the approved GOLD WASHER OPENING: the painted mouth ring (thick polished band,
21	 *             thin bright lips, dark groove) unwrapped from the approved pixels and straightened (tools/match04/mouth04.py
22	 *             -> tile_mouth.png) on a modeled mouth ring flush with the painted ring plane, mapped through the projector so
23	 *             the approach continues the approved view; its row of glowing bulbs (the painted hot spots on both lips,
24	 *             mouth04.json) drawn as crisp glowing bulbs at any distance.
25	 * Without `?match04=1` nothing here runs; without the sub-switches nothing here is built.
26	 */
27	import * as THREE from 'three';
28	import { PROJ05_INVERSE } from '../vfx/waterRibbon';
29	
30	const QS = new URLSearchParams(location.search);
31	const on = (k: string) => QS.get(k) === '1';
32	export const M04 = {
33	  ring: on('m04ring'),
34	  foam: on('m04foam'),
35	  bub: on('m04bub'),
36	  arrow: on('m04arrow'),
37	  wave: on('m04wave'),
38	  river: on('m04river'),
39	  gold: on('m04gold'),
40	  mouth: on('m04mouth'),
41	  room: on('m04room'),
42	  foam3: on('m04foam3'),
43	  pink: on('m04pink'),
44	  arr5: on('m04arr5'),
45	  arr3d: on('m04arr3d'),
46	  lay: on('m04lay'),
47	  num: (k: string, d: number) => (QS.has(k) ? Number(QS.get(k)) : d),
48	};
49	
50	export interface M04Ctx {
51	  group: THREE.Group;
52	  shared: Record<string, THREE.IUniform>;
53	  proj: THREE.PerspectiveCamera;
54	  /** tube axis in group-local coordinates (x lateral, y up from the slide, z = -down the slide) */
55	  cx: number; cy: number; z0: number; len: number; r: number; outerR: number;
56	  hideOld: (names: string[]) => void;
57	}
58	
59	const VERT = /* glsl */ `
60	uniform mat4 uProjVP;
61	attribute vec2 aK;
62	varying vec4 vProj;
63	varying vec3 vW;
64	varying vec3 vN;
65	varying vec2 vK;
66	void main() {
67	  vec4 wp = modelMatrix * vec4(position, 1.0);
68	  vProj = uProjVP * wp;
69	  vW = wp.xyz;
70	  vK = aK;
71	  vN = normalize(mat3(modelMatrix) * normal);
72	  gl_Position = projectionMatrix * viewMatrix * wp;
73	}`;
74	
75	// polished gold, art-directed in DISPLAY colours measured on the approved picture (then pjInverse like the plate):
76	// groove (110,35,5) / shadow band (168,70,18) / mid (205,97,28) / lit (245,143,38) / hot lip (255,204,77) / glint.
77	// Each ring = a broad polished band that brightens toward its lip, a bright rounded lip with hot spots, a thin dark groove;
78	// the far rings warm toward the glowing vanishing point; violet / pink water reflections on the lower walls.
79	const GOLD_FRAG = /* glsl */ `
80	uniform sampler2D uPlate;

450	  }
451	  gl_FragColor = vec4(pjInverse(col), 1.0);
452	}`;
453	
454	/** world-space bubble discs + foam puffs share one tiny shader each (camera-facing sprites in an InstancedMesh) */
455	const SPRITE_VERT = /* glsl */ `
456	attribute vec4 aB;          // xyz world centre, w radius
457	attribute float aS;         // seed
458	uniform vec2 uNear;         // fade sprites out this close to the camera (no giant discs in the face)
459	varying vec2 vUv;
460	varying float vS;
461	varying float vF;
462	void main() {
463	  vUv = uv * 2.0 - 1.0;
464	  vS = aS;
465	  vec4 mv = viewMatrix * vec4(aB.xyz, 1.0);
466	  vF = smoothstep(uNear.x, uNear.y, -mv.z);
467	  mv.xy += position.xy * aB.w * 2.0;
468	  gl_Position = projectionMatrix * mv;
469	}`;
470	const BUB_FRAG = /* glsl */ `
471	uniform vec4 uPjPost;
472	uniform vec2 uPjRes;
473	uniform float uAlpha;
474	varying vec2 vUv;
475	varying float vS;
476	varying float vF;
477	${PROJ05_INVERSE}
478	void main() {
479	  float r = length(vUv);
480	  if (r > 1.0) discard;
481	  // soap bubble: clear centre, iridescent rim (pink -> violet -> cyan around it), white window highlight
482	  float rim = smoothstep(0.55, 0.97, r) * (1.0 - smoothstep(0.97, 1.0, r));
483	  float a = atan(vUv.y, vUv.x) + vS * 6.0;
484	  vec3 iri = 0.5 + 0.5 * cos(vec3(0.0, 2.1, 4.2) + a * 1.0 + r * 3.0);
485	  iri = mix(vec3(0.95, 0.55, 0.95), iri, 0.55);
486	  vec3 col = mix(vec3(0.86, 0.80, 1.0), iri, rim);
487	  float hl = smoothstep(0.24, 0.05, length(vUv - vec2(-0.38, 0.42)));
488	  float alpha = 0.10 + 0.70 * rim + 0.85 * hl;
489	  col = mix(col, vec3(1.0), hl);
490	  gl_FragColor = vec4(pjInverse(col), clamp(alpha, 0.0, 1.0) * uAlpha * vF);
491	}`;
492	const FOAM_FRAG = /* glsl */ `
493	uniform vec4 uPjPost;
494	uniform vec2 uPjRes;
495	uniform float uAlpha;
496	varying vec2 vUv;
497	varying float vS;
498	varying float vF;
499	${PROJ05_INVERSE}
500	void main() {
501	  float r = length(vUv);
502	  if (r > 1.0 || uAlpha * vF < 0.5) discard;
503	  // a painted foam puff: white top-left, lavender-blue / pink shadow low right, soft bright window highlight
504	  vec3 nrm = vec3(vUv, sqrt(max(0.0, 1.0 - r * r)));
505	  float l = clamp(dot(nrm, normalize(vec3(-0.45, 0.6, 0.65))), 0.0, 1.0);
506	  vec3 shade = mix(vec3(0.70, 0.64, 0.95), vec3(0.93, 0.70, 0.92), 0.5 + 0.5 * sin(vS * 11.0));
507	#ifdef FOAM3
508	  // painted glossy foam balls: lavender body, pink bounce light from the water below, white only at the top highlight
509	  shade = mix(vec3(0.66, 0.58, 0.93), vec3(0.95, 0.62, 0.90), 0.5 + 0.5 * sin(vS * 11.0));
510	  vec3 col = mix(shade, vec3(0.93, 0.90, 1.0), smoothstep(0.25, 0.95, l));
511	  col = mix(col, vec3(0.98, 0.55, 0.85), 0.35 * smoothstep(0.2, -0.8, vUv.y));
512	#else
513	  vec3 col = mix(shade, vec3(1.0, 0.99, 1.0), smoothstep(0.10, 0.80, l));
514	#endif
515	  col += vec3(1.0) * 0.45 * smoothstep(0.22, 0.0, length(vUv - vec2(-0.30, 0.36)));
516	  col = mix(col, shade * 0.92, 0.30 * smoothstep(0.88, 1.0, r));
517	  gl_FragColor = vec4(pjInverse(clamp(col, 0.0, 1.0)), 1.0);
518	}`;
519	
520	// m04mouth: a glowing bulb on the washer opening — white-hot core, yellow glow, soft amber halo, a faint vertical light
521	// streak across the band (as painted); vS = brightness
522	const BULB_FRAG = /* glsl */ `
523	uniform vec4 uPjPost;
524	uniform vec2 uPjRes;
525	uniform float uAlpha;
526	varying vec2 vUv;
527	varying float vS;
528	varying float vF;
529	${PROJ05_INVERSE}
530	void main() {
531	  float r = length(vUv);
532	  if (r > 1.0) discard;
533	  float core = smoothstep(0.17, 0.09, r);
534	  float glow = exp(-r * r / 0.06);
535	  float halo = exp(-r * r / 0.30) * (1.0 - smoothstep(0.7, 1.0, r));
536	  float streak = exp(-vUv.x * vUv.x / 0.008) * exp(-vUv.y * vUv.y / 0.30) * 0.6;
537	  vec3 col = mix(vec3(1.0, 0.62, 0.16), vec3(1.0, 0.86, 0.42), clamp(glow + streak, 0.0, 1.0));
538	  col = mix(col, vec3(1.0, 0.99, 0.90), core);
539	  float a = clamp(core + 0.85 * glow + 0.35 * halo + streak, 0.0, 1.0) * (0.75 + 0.25 * vS);
540	  gl_FragColor = vec4(pjInverse(col), a * uAlpha * vF);
541	}`;
542	
543	function lathe(prof: { r: number; a: number; part: number }[], segs: number, ringIdx: (i: number) => number) {
544	  const pts = prof.map((p) => new THREE.Vector2(p.r, p.a));
545	  const g = new THREE.LatheGeometry(pts, segs);
546	  const n = g.attributes.position.count;
547	  const k = new Float32Array(n * 2);
548	  // LatheGeometry: vertex index = seg * pts.length + j
549	  for (let i = 0; i < n; i++) { const j = i % pts.length; k[i * 2] = prof[j].part; k[i * 2 + 1] = ringIdx(j); }
550	  g.setAttribute('aK', new THREE.Float32BufferAttribute(k, 2));
551	  g.deleteAttribute('uv');
552	  return g;
553	}
554	
555	export function addM04(ctx: M04Ctx) {
556	  const { group, shared, proj, cx, cy, z0, len, r } = ctx;
557	  const any = M04.ring || M04.foam || M04.bub || M04.arrow || M04.wave || M04.river;
558	  if (!any) return null;
559	  group.updateMatrixWorld(true);
560	  const Mw = group.matrixWorld;
561	  const toW = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z).applyMatrix4(Mw);
562	  const axO = toW(cx, cy, z0), axD = toW(cx, cy, z0 - 1).sub(axO).normalize();
563	  const axU = toW(cx, cy + 1, z0).sub(axO).normalize(), axR = toW(cx + 1, cy, z0).sub(axO).normalize();
564	  const away = { value: 0 };
565	  const fade = (M04.num('m04fade0', 0.3)), fade1 = M04.num('m04fade1', 2.5);
566	  const out: { update(cam: THREE.Vector3, benny?: THREE.Vector3): void } = { update() {} };
567	  const updaters: ((a: number) => void)[] = [];
568	
569	  if (M04.ring) {
570	    const ringTile = new THREE.TextureLoader().load(new URL('../../assets/textures/match04/tile_ring.png', import.meta.url).href, (t) => { t.needsUpdate = true; });
571	    ringTile.colorSpace = THREE.NoColorSpace; ringTile.flipY = false; ringTile.wrapS = THREE.RepeatWrapping; ringTile.wrapT = THREE.ClampToEdgeWrapping;
572	    ringTile.minFilter = THREE.LinearMipmapLinearFilter; ringTile.anisotropy = 8;
573	    const gm = new THREE.ShaderMaterial({
574	      vertexShader: VERT, fragmentShader: GOLD_FRAG, side: THREE.DoubleSide, fog: false, extensions: { derivatives: true } as never,
575	      uniforms: { uPlate: shared.uPlate, uPjPost: shared.uPjPost, uPjRes: shared.uPjRes, uProjVP: shared.uProjVP,
576	        uAway: away, uAxO: { value: axO }, uAxD: { value: axD }, uAxU: { value: axU }, uAxR: { value: axR }, uNB: { value: M04.num('m04nb', 28) },
577	        uP: { value: M04.num('m04ringp', 2.6) }, uLipBulb: { value: M04.num('m04lipbulb', 1) }, uBulbR: { value: (r + ctx.outerR) / 2 }, uLen: { value: len }, uRingTile: { value: ringTile }, uPaint: { value: M04.num('m04paint', M04.gold ? 0.8 : 1.4) }, uGoldY: { value: M04.gold ? 1 : 0 }, uCopper: { value: M04.num('m04copper', 0) }, uBulge: { value: M04.num('m04bulge', 0) }, uMouthT: { value: 0 }, uMouthTex: { value: null }, uMouthRho: { value: new THREE.Vector3(4.45, 3.25, M04.num('m04mro', -0.10)) }, uProjPos: shared.uProjPos, uTone: { value: new THREE.Vector4(M04.num('m04tb', 0.11), M04.num('m04tl', 0.38), M04.num('m04tm', 0.5), M04.num('m04ts', 0.45)) } },
578	    });
579	    const gw = M04.num('m04ringgw', 1);

700	      const k = THREE.MathUtils.smoothstep(a, -0.6, 1.4);
701	      for (let i = 0; i <= nX; i++) { pos.push(cx + xs[i].x, 0.02 + (xs[i].y - 0.02) * k, z0 - a); aR.push(arc[i], 0); }
702	    }
703	    for (let j = 0; j < nT; j++) for (let i = 0; i < nX; i++) {
704	      const p0 = j * (nX + 1) + i, p1 = p0 + 1, p2 = p0 + nX + 1, p3 = p2 + 1;
705	      idx.push(p0, p2, p1, p1, p2, p3);
706	    }
707	    const g = new THREE.BufferGeometry();
708	    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
709	    g.setAttribute('aR', new THREE.Float32BufferAttribute(aR, 2));
710	    g.setIndex(idx);
711	    const riv = new THREE.TextureLoader().load(new URL('../../assets/textures/match04/tile_river3.png', import.meta.url).href, (t) => { t.needsUpdate = true; });
712	    riv.colorSpace = THREE.NoColorSpace; riv.flipY = false; riv.wrapS = riv.wrapT = THREE.RepeatWrapping;
713	    riv.minFilter = THREE.LinearMipmapLinearFilter; riv.anisotropy = 8;
714	    // tiles04.json river3: lateral +-4 u, along 1.757 .. 6.409 u from Benny's checkpoint water point
715	    const rm = new THREE.ShaderMaterial({ vertexShader: RIVER_VERT, fragmentShader: RIVER_FRAG, side: THREE.DoubleSide, fog: false,
716	      extensions: { derivatives: true } as never, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -4,
717	      uniforms: { uPlate: shared.uPlate, uPjPost: shared.uPjPost, uPjRes: shared.uPjRes, uProjVP: shared.uProjVP, uAway: away,
718	        uRiv: { value: riv }, uRivA: { value: new THREE.Vector4(4, 1.7572621, 4.6517529, M04.num('m04rk', 1.0)) }, uTime: time,
719	        uArr: { value: new THREE.Vector4(M04.num('m04ap', 5.6), 9.58, M04.num('m04aw', 1.0), M04.num('m04at', 0.21)) }, uZ0: { value: z0 },
720	        uLane: { value: new THREE.Vector3(M04.num('m04lane', 0), M04.num('m04lanew', 1.9), M04.num('m04lanes', 0.85)) },
721	        uLane3: { value: new THREE.Vector2(M04.num('m04lcd', 0), M04.num('m04lcw', 1.6)) },
722	        uLane4: { value: (() => { const s = (new URLSearchParams(location.search).get('m04lcn') ?? '').split(',').map(Number);
723	          return s.length === 2 && s.every(Number.isFinite) ? new THREE.Vector2(s[0], s[1]) : new THREE.Vector2(0, 0); })() },
724	        uLane2: { value: new THREE.Vector4(M04.num('m04lane2', 0), M04.num('m04lgl', 1.0), M04.num('m04lsp', 0.9), M04.num('m04lbr', 0)) },
725	        uEdge: { value: new THREE.Vector4(M04.num('m04edge', 0), arc[nX], M04.num('m04edgew', 0.45), M04.num('m04edges', 0.8)) },
726	        uSE: { value: new THREE.Vector2(M04.num('m04rse', 1), M04.num('m04rsl', 1.2)) },
727	        uPk: { value: new THREE.Vector4(M04.pink ? 1 : 0, M04.num('m04pkl', 1.05), M04.num('m04pko', 3.6), M04.num('m04pkw', 0.85)) },
728	        uPkH: { value: M04.num('m04pkh', 0) },
729	        uA5: { value: new THREE.Vector4(M04.arr5 ? 1 : 0, M04.num('m04a5p', 3.3), M04.num('m04a5f', 11.6), M04.num('m04a5t', 1.45)) },
730	        uA5b: { value: a5b }, uA5n: { value: new THREE.Vector2(M04.num('m04a5n0', 6.5), M04.num('m04a5n1', 9.0)) } } });
731	    const rmesh = new THREE.Mesh(g, rm); rmesh.name = 'm04_river'; rmesh.renderOrder = 1; group.add(rmesh);
732	    console.info('[match04] m04river', { xW, RY, XF });
733	  }
734	
735	  // sprite clouds (foam puffs, bubbles): world positions computed in the slide-local frame
736	  const sprites = (items: { p: THREE.Vector3; r: number; s: number }[], frag: string, name: string, order: number, opaque = false, near = [1.2, 2.6]) => {
737	    const quad = new THREE.PlaneGeometry(1, 1);
738	    const g = new THREE.InstancedBufferGeometry();
739	    g.setIndex(quad.index); g.setAttribute('position', quad.attributes.position); g.setAttribute('uv', quad.attributes.uv);
740	    const aB = new Float32Array(items.length * 4), aS = new Float32Array(items.length);
741	    items.forEach((it, i) => { const w = it.p.clone().applyMatrix4(Mw); aB.set([w.x, w.y, w.z, it.r], i * 4); aS[i] = it.s; });
742	    g.setAttribute('aB', new THREE.InstancedBufferAttribute(aB, 4));
743	    g.setAttribute('aS', new THREE.InstancedBufferAttribute(aS, 1));
744	    g.instanceCount = items.length;
745	    const alpha = { value: 0 };
746	    const m = new THREE.ShaderMaterial({ vertexShader: SPRITE_VERT, fragmentShader: frag, transparent: !opaque, depthWrite: opaque, fog: false,
747	      uniforms: { uPjPost: shared.uPjPost, uPjRes: shared.uPjRes, uAlpha: alpha, uNear: { value: new THREE.Vector2(near[0], near[1]) } } });
748	    const mesh = new THREE.Mesh(g, m);
749	    mesh.name = name; mesh.frustumCulled = false; mesh.renderOrder = order; mesh.visible = false; // invisible during the projector depth bake
750	    group.add(mesh);
751	    updaters.push((a) => { alpha.value = a; mesh.visible = a > 0.01; });
752	  };
753	  let seed = 4321; const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
754	  const waterHalf = Math.sqrt(Math.max(0, r * r - cy * cy)); // where the water meets the tunnel wall
755	  if (M04.foam && M04.river) {
756	    // the painted foam clouds: big white puffy balls piled along both river edges where the river meets the gold wall,
757	    // in clusters of varied size with short gaps, plus bigger banks before the opening
758	    const items: { p: THREE.Vector3; r: number; s: number }[] = [];
759	    // `m04foam2` (default with m04foam under m04river): irregular heaped clumps instead of evenly spaced rows
760	    const heaped = M04.num('m04foam2', 1) > 0.5;
761	    // r14 `&m04foamr=L`: the painted foam clouds sit round the ENTRANCE RIM only — the edge banks stop L u inside the
762	    // opening (user: no foam walls inside the tunnel); the banks before the opening stay
763	    const rimL = M04.num('m04foamr', 1e9);
764	    for (const side of [-1, 1]) {
765	      let a = 0.2 + rnd() * 0.5;
766	      while (heaped && a < Math.min(len - 1, rimL)) {
767	        const f3 = M04.foam3;                                     // round 9: low soft banks hugging the river edge
768	        const cl = 0.5 + Math.pow(rnd(), 1.3) * 2.4;            // clump length along the river
769	        const H = (0.2 + Math.pow(rnd(), 1.8) * 1.1) * (f3 ? 0.35 : 1);   // heap height (a few tall heaps, many low ones)
770	        const reach = (0.3 + rnd() * 0.5 + H * 0.6) * (f3 ? 0.6 : 1);     // how far the clump spills into the river
771	        const n = Math.round((6 + cl * (8 + H * 22)) * (f3 ? 0.75 : 1));
772	        const lean = (rnd() - 0.5) * 0.6;
773	        for (let i = 0; i < n; i++) {
774	          const t = rnd(), env = Math.pow(Math.sin(Math.PI * t), 0.7);
775	          const hf = Math.pow(rnd(), 1.6) * env;                 // height fraction inside the heap
776	          const big = rnd() < 0.18;
777	          const rad = (big ? 0.28 + rnd() * 0.30 : 0.06 + Math.pow(rnd(), 1.7) * 0.24) * (1 - 0.45 * hf) * (f3 ? (big ? 0.5 : 0.75) : 1);
778	          const d = Math.min(xW - XF + 0.4, rnd() * reach * env + lean * t * 0.5);   // inward from the wall
779	          const onWall = rnd() < (f3 ? 0.08 : 0.25);              // some puffs heaped up the lower wall
780	          const tt = Math.max(0, 1 - Math.max(0, d) / Math.max(0.1, xW - XF));
781	          const ys = onWall ? RY + rnd() * (f3 ? 0.25 : 0.7) * env : 0.02 + RY * tt * tt;
782	          const x = side * (onWall ? xW - 0.12 - rnd() * 0.15 : XF + (xW - XF) * tt - 0.05);
783	          const y = ys + rad * (0.25 + 0.4 * rnd()) + hf * H;
784	          if (Math.hypot(x, y - cy) > r - 0.08) continue;
785	          items.push({ p: new THREE.Vector3(cx + x, y, z0 - a - t * cl), r: rad, s: rnd() });
786	        }
787	        a += cl + 0.1 + Math.pow(rnd(), 1.5) * 2.2 * (f3 ? 1.6 : 1);   // irregular gaps (wider: the pink water shows)
788	      }
789	      while (!heaped && a < len - 1) {
790	        const cl = 1.2 + rnd() * 2.2, n = Math.round(cl * (9 + rnd() * 6));
791	        for (let i = 0; i < n; i++) {
792	          const t = rnd(), env = Math.sin(Math.PI * t);
793	          const rad = 0.10 + Math.pow(rnd(), 1.4) * 0.34 * (0.5 + 0.5 * env);
