const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('console', async (m) => {
    if (!m.text().includes('[match04]')) return;
    const vals = await Promise.all(m.args().map((a) => a.jsonValue().catch(() => '?')));
    console.log(JSON.stringify(vals));
  });
  await page.goto(`${vite.url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  await page.evaluate(() => window.__rainbow.goto('04'));
  await page.waitForTimeout(1500);
  const geo = await page.evaluate(() => {
    const out = {};
    window.__rainbow.scene?.traverse?.((o) => { if (o.name && o.name.startsWith('m04_')) out[o.name] = (out[o.name] ?? 0) + 1; });
    return out;
  }).catch(() => ({}));
  console.log('objects', JSON.stringify(geo));
} finally {
  await browser.close(); await vite.close();
}

